const {chromium}=require('playwright-core'),assert=require('node:assert/strict'),fs=require('node:fs');
(async()=>{fs.mkdirSync('evidence',{recursive:true});const b=await chromium.launch({executablePath:process.env.CHROME_PATH,headless:true,args:['--no-sandbox']});try{
for(const width of [320,390,1280]){let p=await b.newPage({viewport:{width,height:844},isMobile:width<500,hasTouch:width<500});p.setDefaultTimeout(8000);let errors=[];p.on('pageerror',e=>errors.push(e.message));p.on('dialog',d=>d.accept());await p.goto('http://127.0.0.1:8765/wingspan/',{waitUntil:'domcontentloaded'});await p.waitForFunction(()=>DB?.version===6);
assert.equal(await p.evaluate(()=>DB.birds.filter(x=>['guided','deterministic'].includes(x.mechanic.mode)).length),296);
await p.evaluate(()=>{S.stockKnown=true;S.roundKnown=true;S.r=2;S.t=0;S.first=0;S.stock.seed=1;S.stock.worm=1;S.stock.eggs=1;renderAll()});
await p.locator('#forecastPanel summary').click();await p.waitForFunction(()=>document.querySelectorAll('#forecast li').length===11,{},{timeout:8000});assert.equal(await p.locator('#forecast li').count(),11);assert.match(await p.locator('#forecast').innerText(),/неопределённости/);
await p.screenshot({path:'evidence/home-'+width+'.png',fullPage:true});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
await p.evaluate(()=>{S.birds=[{...DB.birds.find(x=>x.name==='Cerulean Warbler'),id:'bonus-test',loc:'forest'}];S.stock={worm:0,seed:0,fish:0,rodent:0,fruit:0,nectar:0,eggs:0};S.selectedGoals=[];S.wizard={kind:'play',index:0,queue:[{type:'power',id:'bonus-test'}],before:actionSnapshot()};save();renderAction();document.getElementById('actionDialog').showModal()});
await p.locator('#actionBody select').selectOption('Anatomist');await p.getByRole('button',{name:'Сохранить бонусы'}).click();assert.equal(await p.evaluate(()=>S.selectedGoals.includes('Anatomist')),true);
await p.reload({waitUntil:'domcontentloaded'});await p.waitForFunction(()=>DB?.version===6);await p.getByRole('button',{name:'Продолжить →'}).click();await p.getByRole('button',{name:'Отменить действие'}).click();assert.equal(await p.evaluate(()=>S.selectedGoals.length),0);

await p.evaluate(()=>{S.birds=[{...DB.birds.find(x=>x.name==='House Sparrow'),id:'sparrow-test',loc:'grass',eggsOn:0,tuckedOn:0,cachedOn:0}];S.stock={worm:0,seed:3,fish:0,rodent:0,fruit:0,nectar:0,eggs:0};S.ledgerKnown=true;S.scores=[{},{}];S.wizard={kind:'play',index:0,queue:[{type:'power',id:'sparrow-test'}],before:actionSnapshot()};save();renderAction();document.getElementById('actionDialog').showModal()});
await p.getByRole('button',{name:'-3 Seed · +3 подкладок'}).click();assert.equal(await p.evaluate(()=>S.stock.seed),0);assert.equal(await p.evaluate(()=>S.scores[0].tucked),3);await p.getByRole('button',{name:'Отменить действие'}).click();assert.equal(await p.evaluate(()=>S.stock.seed),3);
await p.evaluate(()=>{S.birds=[{...DB.birds.find(x=>x.name==='Amazon Kingfisher'),id:'kingfisher-test',loc:'water',eggsOn:0,tuckedOn:0,cachedOn:0}];S.feeder=null;S.ledgerKnown=true;S.scores=[{},{}];S.wizard={kind:'play',index:0,queue:[{type:'power',id:'kingfisher-test'}],before:actionSnapshot()};save();renderAction();document.getElementById('actionDialog').showModal()});
for(let i=0;i<5;i++)await p.locator('#actionBody select').nth(i).selectOption(['fish','fish','worm','rodent','seed'][i]);await p.getByRole('button',{name:'Подтвердить кормушку'}).click();await p.screenshot({path:'evidence/feeder-'+width+'.png',fullPage:true});assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await p.getByRole('button',{name:'Запасти 2 · +2 очк.'}).click();assert.equal(await p.evaluate(()=>S.scores[0].cached),2);assert.equal(await p.evaluate(()=>S.feeder.length),3);await p.getByRole('button',{name:'Отменить действие'}).click();assert.equal(await p.evaluate(()=>S.feeder),null);
await p.evaluate(()=>{S.birds=[{...DB.birds.find(x=>x.name==='Acadian Flycatcher'),id:'flycatcher-test',loc:'forest',eggsOn:0,tuckedOn:0,cachedOn:0}];S.ledgerKnown=true;S.scores=[{},{}];S.wizard={kind:'play',index:0,queue:[{type:'power',id:'flycatcher-test'}],before:actionSnapshot()};save();renderAction();document.getElementById('actionDialog').showModal()});
await p.locator('#actionBody input[type=search]').fill('Northern Flicker');await p.getByRole('button',{name:'Northern Flicker',exact:true}).click();await p.getByRole('button',{name:'Получить Invertebrate и запасти 1'}).click();assert.equal(await p.evaluate(()=>S.stock.worm),1);assert.equal(await p.evaluate(()=>S.scores[0].cached),1);await p.getByRole('button',{name:'Отменить действие'}).click();assert.equal(await p.evaluate(()=>S.birds.length),1);
await p.locator('.nav [data-tab="catalog"]').click();await p.locator('#dbQuery').fill('Cerulean Warbler');await p.waitForFunction(()=>document.querySelectorAll('#dbList .dbrow').length===1);assert.match(await p.locator('.fit-rating').innerText(),/Guided power/);
await p.locator('[data-view="cards"]').click();assert.equal(await p.locator('.atlas-card').count(),1);assert.equal(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);assert.deepEqual(errors,[]);await p.close()}
console.log('V6 browser checks PASS at 320/390/1280');
}finally{await b.close()}})().catch(e=>{console.error(e);process.exitCode=1});
